@Injectable()
export class SchedulerService {
  constructor(private notificationService: NotificationService) {}

  @Cron('0 8 * * *')
  async sendDailyNotifications() {
    const users = await this.notificationService.getUsersForDailyNotification();
    for (const user of users) {
      await this.notificationService.sendNotification(user.id, 'Gunluk hatirlatma!');
    }
  }
}

import { useEffect, useRef } from 'react';
import { gsap } from 'gsap';

export const useDynamicCursor = () => {
  const cursorRef = useRef(null);

  useEffect(() => {
    if (!cursorRef.current) {
      cursorRef.current = document.createElement('div');
      cursorRef.current.className = 'dynamic-cursor';
      document.body.appendChild(cursorRef.current);
    }

    const cursor = cursorRef.current;
    const cursorXQuickTo = gsap.quickTo(cursor, 'x', { duration: 0.5, ease: 'power3' });
    const cursorYQuickTo = gsap.quickTo(cursor, 'y', { duration: 0.5, ease: 'power3' });
  }, []);
};

const { exec } = require('child_process');

function getArpTable(callback) {
  exec('arp -a', (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }
    callback(stdout);
  });
}

